  for(let r=0;r<LH;r++){const y=LH-1-r;for(let x=0;x<LW;x++){const i=(r*LW+x)*4,gr=(px[i+1]-Math.max(px[i],px[i+2]))/255,green=Math.max(0,Math.min(1,(gr-.012)/.063));forest[y*LW+x]=green*(.25+.75*Math.min(1,tall[y*LW+x]))}}
